Cette cat&#233;gorie d’objets comprend les ceintures, les ceinturons et tous les objets port&#233;s sur ou autour de la taille.&lt;br /&gt;&lt;br /&gt;Tout le monde peut utiliser un objet merveilleux port&#233; &#224; la taille, &#224; moins que le contraire ne soit indiqu&#233; dans sa description. Ces objets sont habituellement activ&#233;s par usage ou par un mot de commande mais il y a parfois des diff&#233;rences en fonction des objets.&lt;br /&gt;&lt;br /&gt;Tous les objets merveilleux d&#233;crits ci-dessous p&#232;sent entre 500 g et 1,5 kg, sauf la &lt;i&gt;Ceinture de Peau de Pierre&lt;/i&gt; qui p&#232;se 5 kg.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Objets merveilleux port&#233;s &#224; la taille&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Objet&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bande-De-Cabriole.html&quot; title=&quot;Bande de cabriole&quot;&gt;Bande de cabriole&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +4 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour traverser une case menac&#233;e ou occup&#233;e.&lt;/td&gt;&lt;td&gt;800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cartouchi&#232;re-B&#233;n&#233;fique.html&quot; title=&quot;Cartouchi&#232;re B&#233;n&#233;fique&quot;&gt;Cartouchi&#232;re b&#233;n&#233;fique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut stocker jusqu’&#224; 200 munitions d’armes &#224; feu, une trousse d’armurier et une corne &#224; poudre. Permet de recharger une arme &#224; feu par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-M&#233;ridien.html&quot; title=&quot;Ceinturon m&#233;ridien&quot;&gt;Ceinturon m&#233;ridien&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de porter 2 anneaux suppl&#233;mentaires et de changer les 2 actifs par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-&#192;-Lame.html&quot; title=&quot;Ceinture &#224; lame&quot;&gt;Ceinture &#224; lame&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut se transformer en arme tranchante et/ou perforante &#224; volont&#233;, elle peut &#234;tre enchant&#233;e.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Dall&#232;gement-Du-Fardeau.html&quot; title=&quot;Ceinture d&amp;#39;all&#232;gement du fardeau&quot;&gt;ceinture d’all&#232;gement du fardeau&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charge-De-Fourmi.html&quot; title=&quot;Charge de fourmi&quot;&gt;charge de fourmi&lt;/a&gt;&lt;/i&gt; en permanence.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-De-Manœuvres-Sup&#233;rieures.html&quot; title=&quot;Ceinturon de manoeuvres sup&#233;rieures&quot;&gt;Ceinturon de manœuvres sup&#233;rieures&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut conf&#233;rer un bonus d’alt&#233;ration d&#233;pendant du mod&#232;le aux tests d’une &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Manoeuvreoffensive.html&quot; title=&quot;Manœuvre offensive&quot;&gt;manœuvre offensive&lt;/a&gt; au choix, ainsi qu’au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre cette m&#234;me manœuvre pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Lutteur.html&quot; title=&quot;Le lutteur&quot;&gt;lutteur&lt;/a&gt; peut utiliser sa &lt;a class=&quot;pagelink&quot; href=&quot;Lutteur.html#FLEXIBILITEMARTIALE&quot; title=&quot;Le lutteur&quot;&gt;flexibilit&#233; martiale&lt;/a&gt; une fois de plus par jour.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +1&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA &lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +1.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA &lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;| 8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +3&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA &lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +3.&lt;/td&gt;&lt;td&gt;| 18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA &lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 32 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +5&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA &lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +5.&lt;/td&gt;&lt;td&gt;| 50 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;charpe-De-La-Fleur-De-Laube.html&quot; title=&quot;&#201;charpe de la Fleur de l&amp;#39;Aube&quot;&gt;&#201;charpe de la Fleur de l&#39;Aube&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Prot&#232;ge de la chaleur (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Endurance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;Endurance aux &#233;nergies destructives&quot;&gt;endurance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;). Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Feuille-Morte.html&quot; title=&quot;Feuille morte&quot;&gt;feuille morte&lt;/a&gt;&lt;/i&gt;. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Sarenra&#233;-(Technique).html&quot; title=&quot;Sarenra&#233;&quot;&gt;Sarenra&#233;&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers.html&quot; title=&quot;Soins l&#233;gers&quot;&gt;soins l&#233;gers&lt;/a&gt;&lt;/i&gt; une fois par jour (peut &#234;tre d&#233;clench&#233; imm&#233;diatement apr&#232;s &#234;tre tomb&#233; &#224; -1 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;pv&lt;/a&gt; ou moins), et faire briller cet objet comme une &lt;a class=&quot;pagelink&quot; href=&quot;Torche-(Objet).html&quot; title=&quot;Torche&quot;&gt;torche&lt;/a&gt; qui g&#234;ne les cr&#233;atures sensibles &#224; la lumi&#232;re du soleil.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Du-Roi-Serpent.html&quot; title=&quot;Ceinture du Roi serpent&quot;&gt;Ceinture du Roi Serpent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d&#39;alt&#233;ration de +1 &#224; l&#39;armure naturelle. Un suivant d&#39;Ydersius peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Morsure-Magique.html&quot; title=&quot;Morsure magique&quot;&gt;morsure magique&lt;/a&gt;&lt;/i&gt; (porteur uniquement) une fois par jour.&lt;/td&gt;&lt;td&gt;2 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Large-Ceinture-Aquatique.html&quot; title=&quot;Large ceinture aquatique&quot;&gt;Large ceinture aquatique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; et permet de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences#Faire10.html&quot; title=&quot;faire 10&quot;&gt;faire 10&lt;/a&gt; &#224; ces tests, m&#234;me en situation de stress.&lt;/td&gt;&lt;td&gt;2 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-D&#233;quitation.html&quot; title=&quot;Ceinture d&amp;#39;&#233;quitation&quot;&gt;ceinture d’&#233;quitation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +4 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt; et permet de r&#233;ussir automatiquement certains de ces tests tant que le porteur ne porte pas d’armure lourde.&lt;/td&gt;&lt;td&gt;3 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-De-Force-De-G&#233;ant.html&quot; title=&quot;Ceinturon de force de g&#233;ant&quot;&gt;Ceinturon de force de g&#233;ant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; (temporaire pendant les 24 premi&#232;res heures de port).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-De-Dext&#233;rit&#233;-Du-Chat.html&quot; title=&quot;Ceinturon de dext&#233;rit&#233; du chat&quot;&gt;Ceinturon de dext&#233;rit&#233; du chat&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; (temporaire pendant les 24 premi&#232;res heures de port).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-De-Constitution-De-Lours.html&quot; title=&quot;Ceinturon de constitution de l&amp;#39;ours&quot;&gt;ceinturon de constitution de l’ours&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; (temporaire pendant les 24 premi&#232;res heures de port).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Ajust&#233;e.html&quot; title=&quot;Ceinture ajust&#233;e&quot;&gt;Ceinture ajust&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu&#39;&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, peut conf&#233;rer les effets de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Compression.html&quot; title=&quot;Compression&quot;&gt;compression&lt;/a&gt;&lt;/i&gt; ainsi qu&#39;un bonus de +5 aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt;. Une fois par jour, peut conf&#233;rer les effets de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rapetissement.html&quot; title=&quot;Rapetissement&quot;&gt;rapetissement&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Mordante.html&quot; title=&quot;Ceinture mordante&quot;&gt;Ceinture mordante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par round, peut attaquer une cr&#233;ature qui provoque une attaque d’opportunit&#233; pour son porteur.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-Mord-Boyau.html&quot; title=&quot;Ceinturon mord-boyau&quot;&gt;Ceinturon mord-boyau&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-De-Constitution-De-Lours.html&quot; title=&quot;Ceinturon de constitution de l&amp;#39;ours&quot;&gt;ceinturon de constitution de l&#39;ours +2&lt;/a&gt;&lt;/i&gt;. Lorsque le porteur est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Agripp&#233;.html&quot; title=&quot;Agripp&#233;&quot;&gt;agripp&#233;&lt;/a&gt;, blesse l&#39;assaillant comme des &lt;a class=&quot;pagelink&quot; href=&quot;Armure-&#192;-Pointes-(Arme).html&quot; title=&quot;Armure &#224; pointes&quot;&gt;pointes d&#39;armure&lt;/a&gt; (qui peuvent &#234;tre alt&#233;r&#233;es par magie). Le porteur peut consommer de la viande par le biais de l&#39;objet.&lt;/td&gt;&lt;td&gt;4 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cha&#238;nes-Bris&#233;es-De-La-B&#234;te.html&quot; title=&quot;Cha&#238;nes bris&#233;es de la b&#234;te&quot;&gt;Cha&#238;nes bris&#233;es de la b&#234;te&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de convoquer une cr&#233;ature Mauvaise de la liste de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres-I.html&quot; title=&quot;Convocation de monstres I&quot;&gt;convocation de monstres I&lt;/a&gt;&lt;/i&gt;. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Rovagug-(Technique).html&quot; title=&quot;Rovagug&quot;&gt;Rovagug&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rage.html&quot; title=&quot;Rage&quot;&gt;rage&lt;/a&gt;&lt;/i&gt; une fois par jour (se d&#233;clenche automatiquement si le porteur est entrav&#233;).&lt;/td&gt;&lt;td&gt;4 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-R&#233;cup&#233;ration-Darmes.html&quot; title=&quot;Ceinture de r&#233;cup&#233;ration d&amp;#39;armes&quot;&gt;ceinture de r&#233;cup&#233;ration d’armes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut stocker jusqu’&#224; 4 armes de corps &#224; corps l&#233;g&#232;res qui reviennent &#224; elle lorsque le porteur la l&#226;che.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Du-Rat-Contamin&#233;.html&quot; title=&quot;Ceinture du rat contamin&#233;&quot;&gt;Ceinture du rat contamin&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port). Trois fois par jour, permet de relancer un jet de sauvegarde pour r&#233;sister aux maladies ou au poison.&lt;/td&gt;&lt;td&gt;5 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Du-Rat-Contamin&#233;-Sup&#233;rieure.html&quot; title=&quot;Ceinture du rat contamin&#233; sup&#233;rieure&quot;&gt;Ceinture du rat contamin&#233; sup&#233;rieure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme la &lt;i&gt;Ceinture du Rat Contamin&#233;&lt;/i&gt; mais conf&#232;re &#233;galement un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port).&lt;/td&gt;&lt;td&gt;| 11 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-Subsistance.html&quot; title=&quot;Ceinture de subsistance&quot;&gt;Ceinture de subsistance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Facilite grandement les voyages en terrain hostile et permet d’y trouver plus facilement de la nourriture et de l’eau.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kilt-De-La-Vague-De-Vent.html&quot; title=&quot;Kilt de la vague de vent&quot;&gt;Kilt de la vague de vent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +3 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt;. Flotte sur l&#39;eau quand il n&#39;est pas port&#233;, permettant &#224; des cr&#233;atures de s&#39;y maintenir. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Gozreh-(Technique).html&quot; title=&quot;Gozreh&quot;&gt;Gozreh&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tat-Gazeux.html&quot; title=&quot;&#201;tat gazeux&quot;&gt;&#233;tat gazeux&lt;/a&gt;&lt;/i&gt; une fois par jour (sous cet effet, permet d&#39;entrer dans les liquides et d&#39;y obtenir une vitesse de nage de 3 m), et boire l&#39;eau de mer comme si elle &#233;tait douce.&lt;/td&gt;&lt;td&gt;7 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Reptilienne.html&quot; title=&quot;Ceinture reptilienne&quot;&gt;Ceinture reptilienne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +2 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt; et un bonus de +4 aux jets de sauvegarde contre les poisons. Une fois par jour, peut se transformer en &lt;a class=&quot;pagelink&quot; href=&quot;Serpent-Venimeux.html&quot; title=&quot;Serpent, Serpent venimeux&quot;&gt;serpent venimeux&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Serpent-Constricteur.html&quot; title=&quot;Serpent, Serpent constricteur&quot;&gt;constricteur&lt;/a&gt; pendant 1 heure maximum.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Reptilienne-Sup&#233;rieure.html&quot; title=&quot;Ceinture reptilienne sup&#233;rieure&quot;&gt;Ceinture reptilienne sup&#233;rieure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme la &lt;i&gt;Ceinture Reptilienne&lt;/i&gt; mais conf&#232;re &#233;galement un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; et &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port) et lui permet d’appliquer un arch&#233;type simple au serpent dont elle prend la forme.&lt;/td&gt;&lt;td&gt;| 20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Simiesque.html&quot; title=&quot;Ceinture simiesque&quot;&gt;Ceinture simiesque&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port) et rend l’escalade moins dangereuse. Une fois par jour, peut se transformer en queue pr&#233;hensile capable d’attaquer et de manipuler des objets pendant 5 minutes maximum.&lt;/td&gt;&lt;td&gt;9 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Simiesque-Sup&#233;rieure.html&quot; title=&quot;Ceinture simiesque sup&#233;rieure&quot;&gt;Ceinture simiesque sup&#233;rieure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme la &lt;i&gt;Ceinture Simiesque&lt;/i&gt; mais conf&#232;re &#233;galement un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port) et un bonus de circonstances de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; tant la queue pr&#233;hensile est active.&lt;/td&gt;&lt;td&gt;| 18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-De-Puissance-De-G&#233;ant.html&quot; title=&quot;Ceinturon de puissance de g&#233;ant&quot;&gt;Ceinturon de puissance de g&#233;ant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; la valeur de deux caract&#233;ristiques physiques (temporaire pendant les 24 premi&#232;res heures de port).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;10 000 p&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 40 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 90 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-La-Belette.html&quot; title=&quot;Ceinture de la belette&quot;&gt;Ceinture de la belette&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port), permet de se d&#233;placer &#224; la moiti&#233; de sa vitesse &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#192;terre.html&quot; title=&quot;&#192; terre&quot;&gt;&#224; terre&lt;/a&gt; et de ne pas subir les effets n&#233;gatifs de cet &#233;tat. Conf&#232;re le pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Compression-(Capacit&#233;).html&quot; title=&quot;Compression (Ext)&quot;&gt;compression&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-Charge-Tonitruante.html&quot; title=&quot;Ceinture de charge tonitruante&quot;&gt;Ceinture de charge tonitruante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port) et renforce les &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#CHARGE&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;charges&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;10 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Du-Minotaure.html&quot; title=&quot;Ceinture du minotaure&quot;&gt;Ceinture du minotaure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port) et permet d&#39;ignorer le &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement-Et-Position.html#TERRAINDIFFICILE&quot; title=&quot;D&#233;placement et position&quot;&gt;terrain difficile&lt;/a&gt; lors d&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Charge.html&quot; title=&quot;charge&quot;&gt;charge&lt;/a&gt;, d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Renversement.html&quot; title=&quot;renversement&quot;&gt;renversement&lt;/a&gt; ou d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Pi&#233;tinement-(Capacit&#233;).html&quot; title=&quot;Pi&#233;tinement (Ext)&quot;&gt;pi&#233;tinement&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;11 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-Sant&#233;.html&quot; title=&quot;Ceinture de sant&#233;&quot;&gt;Ceinture de sant&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet d’ignorer les effets des &#233;tats &lt;a class=&quot;pagelink&quot; href=&quot;../&#201;tats pr&#233;judiciables#Fatigu&#233;

Un personnage fatigu&#233; est dans l’incapacit&#233; de courir et de charger/-Il-Subit-Un-Malus-De--2-En-Force-Ainsi-Qu’En-Dext&#233;rit&#233;.html&quot; title=&quot;Fatigu&#233;&quot;&gt;fatigu&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secou&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreux&lt;/a&gt; tant que le porteur se d&#233;place d’1,5 m maximum pendant son tour.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-Surveillance.html&quot; title=&quot;Ceinture de surveillance&quot;&gt;Ceinture de surveillance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Assure une meilleur protection/dissimulation des objets port&#233;s par le porteur. Une fois par jour, permet de r&#233;duire un objet (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-Dobjet.html&quot; title=&quot;R&#233;duction d&amp;#39;objet&quot;&gt;r&#233;duction d’objet&lt;/a&gt;&lt;/i&gt;) et de lui rendre sa taille plus tard.&lt;/td&gt;&lt;td&gt;12 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kilt-De-Guerre-De-Sarenrae.html&quot; title=&quot;Kilt de guerre du derviche&quot;&gt;kilt de guerre du derviche&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et un bonus de comp&#233;tence de +2 aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;. Une fois par jour, permet au porteur de d&#233;penser son &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Diverses#Pasdeplacement.html&quot; title=&quot;Pas de placement&quot;&gt;pas de placement&lt;/a&gt; du tour suivant pour suivre une cr&#233;ature qui en fait un dans une direction oppos&#233;e &#224; lui.&lt;/td&gt;&lt;td&gt;13 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-Jet.html&quot; title=&quot;Ceinture de jet&quot;&gt;Ceinture de jet&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port) et renforce les attaques avec des &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html#ARMEDEJET&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;armes de jet&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;14 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-Jet-Sup&#233;rieure.html&quot; title=&quot;Ceinture de jet sup&#233;rieure&quot;&gt;Ceinture de jet sup&#233;rieure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme la &lt;i&gt;Ceinture de Jet&lt;/i&gt; mais conf&#232;re &#233;galement un bonus d’alt&#233;ration de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port) et la propri&#233;t&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Boomerang.html&quot; title=&quot;boomerang (propri&#233;t&#233;)&quot;&gt;boomerang&lt;/a&gt; &#224; certaines armes de jet lanc&#233;s par le porteur.&lt;/td&gt;&lt;td&gt;| 42 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Des-Nains.html&quot; title=&quot;Ceinture des nains&quot;&gt;Ceinture des nains&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; et de comp&#233;tences bas&#233;es sur le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; de +4 avec les nains, +2 avec les gnomes et les halfelins, et un malus de -2 face &#224; toutes les autres races. Le porteur obtient plusieurs traits raciaux des nains.&lt;/td&gt;&lt;td&gt;14 900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Corde-De-T&#233;nacit&#233;.html&quot; title=&quot;Corde de t&#233;nacit&#233;&quot;&gt;Corde de t&#233;nacit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port) et permet de mieux r&#233;sister aux effets de fatigue et d’&#233;puisement.&lt;/td&gt;&lt;td&gt;15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Daction-Impossible.html&quot; title=&quot;Ceinture d&amp;#39;action impossible&quot;&gt;Ceinture d&#39;action impossible&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet d&#39;effecuter des &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html&quot; title=&quot;Les manœuvres offensives&quot;&gt;manœuvres offensives&lt;/a&gt; contre des adversaires trop grands. Permet de se d&#233;placer et de &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Charge.html&quot; title=&quot;charger&quot;&gt;charger&lt;/a&gt; normalement &#224; travers le &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement-Et-Position#Terraindifficile.html&quot; title=&quot;terrain difficile&quot;&gt;terrain difficile&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-De-La-Perfection-Physique.html&quot; title=&quot;Ceinturon de la perfection physique&quot;&gt;Ceinturon de la perfection physique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; la valeur de toutes les caract&#233;ristiques physiques (temporaire pendant les 24 premi&#232;res heures de port).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 64 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 144 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Anneaux-De-Lanaconda.html&quot; title=&quot;Anneaux de l&amp;#39;anaconda&quot;&gt;anneaux de l’anaconda&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port), un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#LUTTE&quot; title=&quot;Les manœuvres offensives&quot;&gt;lutte&lt;/a&gt; et le pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Constriction-(Capacit&#233;).html&quot; title=&quot;Constriction (Ext)&quot;&gt;constriction&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;18 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Des-H&#233;ros-D&#233;chus.html&quot; title=&quot;Ceinture des h&#233;ros d&#233;chus&quot;&gt;Ceinture des h&#233;ros d&#233;chus&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut convoquer un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alli&#233;-Spirituel.html&quot; title=&quot;Alli&#233; spirituel&quot;&gt;alli&#233; spirituel&lt;/a&gt;&lt;/i&gt; conf&#233;rant un bonus d’intuition de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;21 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-La-Gorgone.html&quot; title=&quot;Ceinture de la gorgone&quot;&gt;Ceinture de la gorgone&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port) et r&#233;duit l’impact des terrains difficiles. Une fois par jour, permet de cracher un c&#244;ne de 18 m de long &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Paralys&#233;.html&quot; title=&quot;Paralys&#233;&quot;&gt;paralysant&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;23 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-Terre-&#201;l&#233;mentaire.html&quot; title=&quot;Ceinture de terre &#233;l&#233;mentaire&quot;&gt;Ceinture de terre &#233;l&#233;mentaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port) et immunise contre les d&#233;placements involontaires. Une fois par jour, le porteur prendre la forme d’un &#233;l&#233;mentaire de terre de taille G (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Corps-&#201;l&#233;mentaire-Iii.html&quot; title=&quot;Corps &#233;l&#233;mentaire III&quot;&gt;corps &#233;l&#233;mentaire III&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;24 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;charpe-De-D&#233;viation.html&quot; title=&quot;&#201;charpe de d&#233;viation&quot;&gt;&#201;charpe de d&#233;viation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet au porteur de tenter une attaque &#224; mains nues gratuite pour annuler une attaque r&#233;ussit dirig&#233;e sur lui.&lt;/td&gt;&lt;td&gt;25 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-Lhomme-Poisson.html&quot; title=&quot;Ceinture de l&amp;#39;homme-poisson&quot;&gt;ceinture de l’homme-poisson&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, le porteur peut se transformer en homme-poisson, obtenant plusieurs traits raciaux de ces derniers, pendant 12 heures maximum.&lt;/td&gt;&lt;td&gt;32 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Miroir.html&quot; title=&quot;Ceinture-miroir&quot;&gt;Ceinture-miroir&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d&#39;alt&#233;ration de +2 en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; (temporaire pendant les 24 premi&#232;res heures de port). Trois fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Image-Miroir.html&quot; title=&quot;Image miroir&quot;&gt;image miroir&lt;/a&gt;&lt;/i&gt; (mais les attaques &#224; distance qui d&#233;truisent des doubles sont renvoy&#233;es &#224; leur lanceur avec le m&#234;me &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d&#39;attaque&lt;/a&gt;). Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, la ceinture recr&#233;&#233; un double illusoire &#224; chaque fois que le porteur est touch&#233; par une attaque (dans la limite du sort et m&#234;me s&#39;il n&#39;y en avait plus).&lt;/td&gt;&lt;td&gt;36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Dancrage.html&quot; title=&quot;Ceinture d&amp;#39;ancrage&quot;&gt;ceinture d’ancrage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +5 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre les manoeuvres offensives visants &#224; d&#233;placer le porteur, et aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets similaires. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Mythique.html&quot; title=&quot;mythique&quot;&gt;mythique&lt;/a&gt; cibl&#233; par un effet de t&#233;l&#233;portation peut d&#233;cider de ne pas &#234;tre affect&#233;. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, peut manifester les effets d&#39;une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ancre-Dimensionnelle.html&quot; title=&quot;Ancre dimensionnelle&quot;&gt;ancre dimensionnelle&lt;/a&gt;&lt;/i&gt; dans un rayon de 9m autour du porteur.&lt;/td&gt;&lt;td&gt;60 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-De-Peau-De-Pierre.html&quot; title=&quot;Ceinture de peau de pierre&quot;&gt;Ceinture de peau de pierre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Toutes les 24 heures, conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 10/adamantium, jusqu’&#224; ce que celle-ci ait absorb&#233; 100 points de d&#233;g&#226;ts.&lt;/td&gt;&lt;td&gt;60 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinture-Dintangibilit&#233;.html&quot; title=&quot;Ceinture d&amp;#39;intangibilit&#233;&quot;&gt;ceinture d’intangibilit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +6 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port). Jusqu’&#224; 10 rounds par jour, le porteur peut devenir &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Intangible.html&quot; title=&quot;Intangible&quot;&gt;intangible&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;110 000 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;
